"""Checks on the Power BI project generated by tools/build_powerbi.py."""

import csv
import filecmp
import importlib.util
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("build_powerbi", ROOT / "tools" / "build_powerbi.py")
build_powerbi = importlib.util.module_from_spec(spec)
spec.loader.exec_module(build_powerbi)


def published_columns(path: Path) -> list[str]:
    if path.suffix == ".csv":
        with path.open(encoding="utf-8") as handle:
            return next(csv.reader(handle))
    duckdb = pytest.importorskip("duckdb")
    return [row[0] for row in duckdb.sql(f"DESCRIBE SELECT * FROM '{path.as_posix()}'").fetchall()]


@pytest.mark.parametrize("table", build_powerbi.TABLES, ids=lambda t: t["name"])
def test_report_columns_exist_in_published_tables(table):
    path = ROOT / "data" / "marts" / table["file"]
    if not path.exists():
        pytest.skip(f"{path.name} not published yet")
    missing = [name for name, _ in table["columns"] if name not in published_columns(path)]
    assert not missing


def test_measure_names_are_unique():
    names = [m["name"] for t in build_powerbi.TABLES for m in t["measures"]]
    assert len(names) == len(set(names))


def test_relationships_point_to_known_columns():
    columns = {(t["name"], name) for t in build_powerbi.TABLES for name, _ in t["columns"]}
    for from_table, from_column, to_table, to_column in build_powerbi.RELATIONSHIPS:
        assert (from_table, from_column) in columns
        assert (to_table, to_column) in columns


def assert_same_tree(generated: Path, committed: Path):
    comparison = filecmp.dircmp(generated, committed)
    assert not comparison.left_only and not comparison.right_only and not comparison.diff_files, (
        "powerbi/ is out of date: run python tools/build_powerbi.py"
    )
    for sub in comparison.common_dirs:
        assert_same_tree(generated / sub, committed / sub)


def test_committed_project_matches_generator(tmp_path):
    build_powerbi.write_semantic_model(tmp_path / "model")
    build_powerbi.write_report(tmp_path / "report")
    name = build_powerbi.NAME
    assert_same_tree(tmp_path / "model", ROOT / "powerbi" / f"{name}.SemanticModel")
    assert_same_tree(tmp_path / "report", ROOT / "powerbi" / f"{name}.Report")
